def retrieve(self, query: str, k: int) -> list[str]:
    """Return up to k memory IDs ranked by compile_guard."""
    from oh_no_my_claudecode.guard.compiler import compile_guard
    from oh_no_my_claudecode.storage import SQLiteStorage

    storage: SQLiteStorage = self._storage  # type: ignore[assignment]
    result = compile_guard(storage, query, limit=k)
    reverse_map = {v: k for k, v in self._id_map.items()}
    ranked_corpus_ids: list[str] = []
    for entry in result.entries:
        corpus_id = reverse_map.get(entry.memory_id)
        if corpus_id is not None:
            ranked_corpus_ids.append(corpus_id)
    return ranked_corpus_ids[:k]

def _discover_indexable_files(repo_root: Path) -> list[str]:
    """Return sorted repo-relative paths of all files worth indexing.

    Applies directory exclusions, extension filter, and
    :func:`~oh_no_my_claudecode.codeindex.exclusions.should_index` (path +
    secret-content check).
    """
    found: list[str] = []
    for current_root, dirnames, filenames in os.walk(repo_root):
        dirnames[:] = sorted(
            d for d in dirnames if d not in EXCLUDE_DIRS and not d.startswith(".git")
        )
        for filename in sorted(filenames):
            abs_file = Path(current_root) / filename
            if abs_file.is_symlink():
                continue
            try:
                rel = abs_file.resolve().relative_to(repo_root.resolve()).as_posix()
            except ValueError:
                continue
            if not should_chunk_extension(rel):
                continue
            if not should_index(abs_file, repo_root):
                continue
            found.append(rel)
            if len(found) >= _MAX_FILES:
                break
        if len(found) >= _MAX_FILES:
            break

    found.sort()
    return found

